// B25: kernel-to-kernel gap on one stream, CUDA-graph gap, two-stream concurrency, L2 persistence across kernels.
#include "common.cuh"
__global__ void stamp_kernel(unsigned long long* tin, unsigned long long* tout, int spin_ns, int idx) { if (threadIdx.x == 0 && blockIdx.x == 0) tin[idx] = gtimer(); unsigned long long t0 = gtimer(); while (gtimer() - t0 < (unsigned long long)spin_ns) { } if (threadIdx.x == 0 && blockIdx.x == 0) tout[idx] = gtimer(); }
__global__ void write_kernel(float4* a, size_t n) { for (size_t i = blockIdx.x * (size_t)blockDim.x + threadIdx.x; i < n; i += (size_t)gridDim.x * blockDim.x) a[i] = make_float4(1, 2, 3, 4); }
__global__ void read_kernel(const float4* __restrict__ a, size_t n, float* out) { float4 acc = make_float4(0, 0, 0, 0); for (size_t i = blockIdx.x * (size_t)blockDim.x + threadIdx.x; i < n; i += (size_t)gridDim.x * blockDim.x) { float4 v = a[i]; acc.x += v.x; acc.y += v.y; acc.z += v.z; acc.w += v.w; } if (acc.x + acc.y + acc.z + acc.w == 123456.789f) out[0] = 1; }
int main(int argc, char** argv) {
  int reps = argi(argc, argv, "--reps", 5), sms = sm_count(); double mhz = probe_clock_mhz(); unsigned long long *tin, *tout; CK(cudaMalloc(&tin, 2000 * 8)); CK(cudaMalloc(&tout, 2000 * 8)); std::vector<unsigned long long> hin(2000), hout(2000); Timer t;
  // 1. dependent chain gap
  { std::vector<double> s; for (int r = 0; r < reps; r++) { for (int i = 0; i < 1000; i++) stamp_kernel<<<1, 32>>>(tin, tout, 20000, i); CK(cudaDeviceSynchronize()); CK(cudaMemcpy(hin.data(), tin, 8000, cudaMemcpyDeviceToHost)); CK(cudaMemcpy(hout.data(), tout, 8000, cudaMemcpyDeviceToHost)); std::vector<double> g; for (int i = 1; i < 1000; i++) g.push_back(((double)hin[i] - (double)hout[i - 1]) * 1e-9); std::sort(g.begin(), g.end()); s.push_back(g[g.size() / 2]); }
    emit_clocked("kernel_gap_s", "s", s, "{\"kernels\": 1000, \"kernel_us\": 20, \"method\": \"globaltimer at exit of kernel i and entry of i+1 on one stream, median gap\"}", mhz); }
  // 2. graph launch
  { cudaStream_t st; CK(cudaStreamCreate(&st)); cudaGraph_t graph; cudaGraphExec_t exec; CK(cudaStreamBeginCapture(st, cudaStreamCaptureModeGlobal)); for (int i = 0; i < 1000; i++) stamp_kernel<<<1, 32, 0, st>>>(tin, tout, 20000, i); CK(cudaStreamEndCapture(st, &graph)); CK(cudaGraphInstantiate(&exec, graph, 0));
    std::vector<double> s; for (int r = 0; r < reps; r++) { CK(cudaGraphLaunch(exec, st)); CK(cudaStreamSynchronize(st)); CK(cudaMemcpy(hin.data(), tin, 8000, cudaMemcpyDeviceToHost)); CK(cudaMemcpy(hout.data(), tout, 8000, cudaMemcpyDeviceToHost)); std::vector<double> g; for (int i = 1; i < 1000; i++) g.push_back(((double)hin[i] - (double)hout[i - 1]) * 1e-9); std::sort(g.begin(), g.end()); s.push_back(g[g.size() / 2]); }
    emit_clocked("graph_kernel_gap_s", "s", s, "{\"kernels\": 1000, \"kernel_us\": 20, \"method\": \"the same chain captured as a CUDA graph\"}", mhz); }
  // 3. concurrency on two streams
  { cudaStream_t s1, s2; CK(cudaStreamCreate(&s1)); CK(cudaStreamCreate(&s2)); for (int blocks : {24, 48}) { std::vector<double> one, two; for (int r = 0; r < reps; r++) { t.start(); stamp_kernel<<<blocks, 128, 0, s1>>>(tin, tout, 2000000, 0); CK(cudaDeviceSynchronize()); one.push_back(t.stop_ms() * 1e-3); t.start(); stamp_kernel<<<blocks, 128, 0, s1>>>(tin, tout, 2000000, 0); stamp_kernel<<<blocks, 128, 0, s2>>>(tin, tout, 2000000, 1); CK(cudaDeviceSynchronize()); two.push_back(t.stop_ms() * 1e-3); }
      std::sort(one.begin(), one.end()); std::sort(two.begin(), two.end()); double ratio = two[two.size() / 2] / one[one.size() / 2]; char det[2048]; snprintf(det, sizeof det, "{\"blocks_per_kernel\": %d, \"one_kernel_s\": %.4g, \"two_streams_s\": %.4g, \"concurrent\": %s, \"method\": \"two 2 ms kernels on two streams; ratio ~1 = co-run, ~2 = serialized\"}", blocks, one[one.size() / 2], two[two.size() / 2], ratio < 1.5 ? "true" : "false");
      char q[48]; snprintf(q, sizeof q, "concurrent_kernels[blocks=%d]", blocks); emit_clocked(q, "ratio", std::vector<double>{ratio}, det, mhz); } }
  // 4. L2 persistence across kernels: A writes 8 MiB, B reads it; then with a 64 MiB read in between
  { size_t bytes = 8 << 20, n = bytes / 16; float4* a; CK(cudaMalloc(&a, 64 << 20)); float* out; CK(cudaMalloc(&out, 4)); int grid = sms * 8;
    auto bwB = [&](bool flush) { write_kernel<<<grid, 256>>>(a, n); if (flush) read_kernel<<<grid, 256>>>(a + n, (56 << 20) / 16, out); t.start(); read_kernel<<<grid, 256>>>(a, n, out); double ms = t.stop_ms(); return bytes / (ms * 1e-3); };
    std::vector<double> warm, cold; for (int r = 0; r < reps; r++) { warm.push_back(bwB(false)); cold.push_back(bwB(true)); } std::sort(warm.begin(), warm.end()); std::sort(cold.begin(), cold.end());
    bool persists = warm[warm.size() / 2] > 1.5 * cold[cold.size() / 2];
    cudaStreamAttrValue attr = {}; attr.accessPolicyWindow.base_ptr = a; attr.accessPolicyWindow.num_bytes = bytes; attr.accessPolicyWindow.hitRatio = 1.0f; attr.accessPolicyWindow.hitProp = cudaAccessPropertyPersisting; attr.accessPolicyWindow.missProp = cudaAccessPropertyStreaming;
    cudaError_t e = cudaDeviceSetLimit(cudaLimitPersistingL2CacheSize, 4 << 20); cudaError_t e2 = cudaStreamSetAttribute(0, cudaStreamAttributeAccessPolicyWindow, &attr);
    char det[2048]; snprintf(det, sizeof det, "{\"warm_read_bytes_per_s\": %.4g, \"after_64MiB_flush_bytes_per_s\": %.4g, \"persists\": %s, \"persisting_window_api\": \"%s / %s\", \"method\": \"kernel A writes 8 MiB, kernel B reads it at once (warm) or after a 56 MiB read (cold); L2-level warm bandwidth means L2 persists across launches\"}", warm[warm.size() / 2], cold[cold.size() / 2], persists ? "true" : "false", cudaGetErrorString(e), cudaGetErrorString(e2));
    emit_clocked("l2_persists_across_kernels", "bool", std::vector<double>{persists ? 1.0 : 0.0}, det, mhz); emit_clocked("l2_persisting_window_supported", "bool", std::vector<double>{(e == cudaSuccess && e2 == cudaSuccess) ? 1.0 : 0.0}, det, mhz); }
  return 0;
}
